function practiceBuilderSpotlight(subjectKey){
 const isMath=subjectKey==="math",route=isMath?"mathematics-honors":"chemistry-honors";
 return '<section class="shell practice-builder-spotlight"><div class="builder-spotlight-copy"><div class="eyebrow">Personalized practice</div><h2>Practice exactly what you need.</h2><p>Select topics, set the mix from simple to fusion, choose 10–30 questions, and decide whether grading should be lenient, standard, or strict.</p></div><div class="builder-spotlight-options"><span>Choose topics</span><span>Simple → Fusion</span><span>Lenient / Standard / Strict</span><span>Weak-topic follow-up</span></div><a class="btn primary" href="#/grade-10/'+route+'/practice-builder">Build My Practice <span>↗</span></a></section>'
}

function practiceBuilder(subjectKey){
 const P=PRACTICE(),s=P?.subjects?.[subjectKey];if(!s)return notfound();
 const isMath=subjectKey==="math",active=isMath?"Math Practice":"Practice Tests";
 const subjectHome=isMath?"#/grade-10/mathematics-honors":"#/grade-10/chemistry-honors";
 const crumb=isMath?mathCrumbs("Practice Builder"):chemCrumbs("Practice Builder");
 const defaultLevels={simple:25,medium:35,complex:25,fusion:15};
 return header(active)+'<main class="practice-builder-page"><section class="shell innerhero compact-hero">'+crumb+
 '<div class="eyebrow"><span class="signal"></span>Custom practice</div><h1>Build My Practice</h1><p class="lead">Choose exactly what you want to practice, how hard it should be, and how strictly it should be graded.</p></section>'+
 '<section class="shell section builder-shell"><div class="builder-main">'+
 '<div class="builder-panel"><div class="builder-panel-head"><div><div class="micro">Quick starts</div><h2>Start with a preset.</h2></div></div><div class="practice-presets">'+s.presets.map(p=>'<button class="practice-preset" data-preset="'+p.id+'"><strong>'+p.name+'</strong><span>'+p.desc+'</span></button>').join("")+'</div></div>'+
 '<div class="builder-panel"><div class="builder-panel-head"><div><div class="micro">1 · Topics</div><h2>What do you want to work on?</h2></div><button class="builder-link" id="toggleAllTopics">Clear all</button></div><div class="topic-picker">'+s.topics.map((t,i)=>'<label class="topic-choice"><input type="checkbox" name="pb-topic" value="'+esc(t)+'" checked><span><b>'+t+'</b><small>'+String(i+1).padStart(2,"0")+'</small></span></label>').join("")+'</div></div>'+
 '<div class="builder-panel"><div class="builder-panel-head"><div><div class="micro">2 · Difficulty mix</div><h2>How challenging should it be?</h2></div><span class="builder-total" id="difficultyTotal">100%</span></div><div class="difficulty-mixer">'+["simple","medium","complex","fusion"].map(k=>'<label class="difficulty-control '+k+'"><div><strong>'+k[0].toUpperCase()+k.slice(1)+'</strong><span data-level-value="'+k+'">'+defaultLevels[k]+'%</span></div><input type="range" min="0" max="100" step="5" value="'+defaultLevels[k]+'" data-level="'+k+'"></label>').join("")+'</div><div class="difficulty-note" id="difficultyNote">Simple builds fluency. Medium adds transfer. Complex hides the setup. Fusion combines topics.</div></div>'+
 '<div class="builder-panel"><div class="builder-panel-head"><div><div class="micro">3 · Session</div><h2>Set the practice rules.</h2></div></div><div class="session-controls"><label><span>Questions</span><select id="pbCount"><option>10</option><option selected>15</option><option>20</option><option>25</option><option>30</option></select></label><label><span>Feedback</span><select id="pbFeedback"><option value="end" selected>At end</option><option value="immediate">After each question</option></select></label></div><div class="grading-choice">'+Object.entries(P.policies).map(([k,p])=>'<label><input type="radio" name="pb-grading" value="'+k+'" '+(k==="standard"?"checked":"")+'><span><strong>'+p.name+'</strong><small>'+p.desc+'</small></span></label>').join("")+'</div></div>'+
 '</div><aside class="builder-summary"><div class="sticky-builder"><div class="micro">Your session</div><h3 id="pbSummaryTitle">'+s.name+'</h3><div class="summary-metrics"><div><strong id="pbSummaryCount">15</strong><span>questions</span></div><div><strong id="pbSummaryTopics">'+s.topics.length+'</strong><span>topics</span></div><div><strong id="pbSummaryGrade">Standard</strong><span>grading</span></div></div><div class="summary-bars" id="pbSummaryBars"></div><div class="summary-topics" id="pbSummaryTopicList">All topics selected</div><button class="btn primary builder-generate" id="generatePractice">Generate Practice</button><a class="builder-back" href="'+subjectHome+'">Back to subject</a></div></aside></section>'+
 '<section class="shell section generated-practice hidden" id="generatedPractice"><div id="practiceSessionMount"></div></section></main>'+footer()
}
function normalizePracticeLevels(){
 const inputs=[...document.querySelectorAll("[data-level]")],vals=Object.fromEntries(inputs.map(i=>[i.dataset.level,+i.value])),sum=Object.values(vals).reduce((a,b)=>a+b,0);
 if(sum===0){vals.simple=25;vals.medium=35;vals.complex=25;vals.fusion=15}
 const total=Object.values(vals).reduce((a,b)=>a+b,0)||100;
 return Object.fromEntries(Object.entries(vals).map(([k,v])=>[k,Math.round(v/total*100)]))
}
function updatePracticeBuilderSummary(){
 const P=PRACTICE();if(!P)return;
 const route=location.hash.includes("mathematics-honors")?"math":"chemistry",s=P.subjects[route];if(!s)return;
 const topics=[...document.querySelectorAll('input[name="pb-topic"]:checked')].map(x=>x.value),count=+($("#pbCount")?.value||15),grading=document.querySelector('input[name="pb-grading"]:checked')?.value||"standard",levels=normalizePracticeLevels();
 if($("#pbSummaryCount"))$("#pbSummaryCount").textContent=count;
 if($("#pbSummaryTopics"))$("#pbSummaryTopics").textContent=topics.length;
 if($("#pbSummaryGrade"))$("#pbSummaryGrade").textContent=P.policies[grading].name;
 if($("#pbSummaryTopicList"))$("#pbSummaryTopicList").textContent=topics.length===s.topics.length?"All topics selected":topics.length?topics.slice(0,5).join(" · ")+(topics.length>5?" · +"+(topics.length-5):""):"Select at least one topic";
 if($("#pbSummaryBars"))$("#pbSummaryBars").innerHTML=["simple","medium","complex","fusion"].map(k=>'<div><span>'+k+'</span><i><b style="width:'+levels[k]+'%"></b></i><strong>'+levels[k]+'%</strong></div>').join("");
 const sum=[...document.querySelectorAll("[data-level]")].reduce((n,i)=>n+(+i.value),0);if($("#difficultyTotal"))$("#difficultyTotal").textContent=sum+"%";
}
function bindPracticeBuilder(){
 const P=PRACTICE();if(!P||!$(".practice-builder-page"))return;
 const subjectKey=location.hash.includes("mathematics-honors")?"math":"chemistry",s=P.subjects[subjectKey];
 document.querySelectorAll("[data-level]").forEach(i=>i.addEventListener("input",()=>{const out=$('[data-level-value="'+i.dataset.level+'"]');if(out)out.textContent=i.value+"%";updatePracticeBuilderSummary()}));
 document.querySelectorAll('input[name="pb-topic"], input[name="pb-grading"]').forEach(i=>i.addEventListener("change",updatePracticeBuilderSummary));
 $("#pbCount")?.addEventListener("change",updatePracticeBuilderSummary);$("#pbFeedback")?.addEventListener("change",updatePracticeBuilderSummary);
 $("#toggleAllTopics")?.addEventListener("click",()=>{const boxes=[...document.querySelectorAll('input[name="pb-topic"]')],all=boxes.every(x=>x.checked);boxes.forEach(x=>x.checked=!all);$("#toggleAllTopics").textContent=all?"Select all":"Clear all";updatePracticeBuilderSummary()});
 document.querySelectorAll(".practice-preset").forEach(btn=>btn.onclick=()=>{const p=s.presets.find(x=>x.id===btn.dataset.preset);if(!p)return;$("#pbCount").value=p.count;document.querySelectorAll("[data-level]").forEach(i=>{i.value=p.levels[i.dataset.level]||0;const out=$('[data-level-value="'+i.dataset.level+'"]');if(out)out.textContent=i.value+"%"});const g=document.querySelector('input[name="pb-grading"][value="'+p.grading+'"]');if(g)g.checked=true;document.querySelectorAll('input[name="pb-topic"]').forEach(x=>x.checked=true);document.querySelectorAll(".practice-preset").forEach(x=>x.classList.toggle("active",x===btn));updatePracticeBuilderSummary()});
 $("#generatePractice")?.addEventListener("click",()=>{const topics=[...document.querySelectorAll('input[name="pb-topic"]:checked')].map(x=>x.value);if(!topics.length){$("#pbSummaryTopicList").textContent="Select at least one topic before generating.";return}const session=P.build(subjectKey,{topics,count:+$("#pbCount").value,levels:normalizePracticeLevels(),grading:document.querySelector('input[name="pb-grading"]:checked')?.value||"standard",feedback:$("#pbFeedback").value,seed:Date.now()});window.__practiceSession=session;renderGeneratedPractice(session);$("#generatedPractice")?.classList.remove("hidden");$("#generatedPractice")?.scrollIntoView({behavior:"smooth",block:"start"})});
 updatePracticeBuilderSummary()
}
function renderGeneratedPractice(session){
 const P=PRACTICE(),mount=$("#practiceSessionMount");if(!mount||!session)return;const policy=P.policies[session.grading];
 mount.innerHTML='<div class="generated-head"><div><div class="eyebrow">Generated session</div><h2>'+session.count+' questions · '+policy.name+' grading</h2><p>'+session.topics.length+' selected topic'+(session.topics.length===1?"":"s")+' · '+(session.feedback==="immediate"?"feedback after each question":"feedback at the end")+'</p></div><button class="btn" id="rebuildPractice">Rebuild</button></div><div class="generated-progress"><i id="practiceProgress"></i><span id="practiceProgressText">0 / '+session.count+' answered</span></div><div class="generated-question-list">'+session.questions.map((q,i)=>'<article class="mcq generated-q" data-pb-q="'+i+'"><div class="qtop"><span class="cat">'+esc(q.topic)+'</span><span class="difficulty-tag '+q.difficulty+'">'+q.difficulty+'</span></div><h3>'+q.q+'</h3><div class="choices">'+q.options.map((o,j)=>'<label><input type="radio" name="pb-'+session.id+'-'+i+'" value="'+j+'"><span>'+o+'</span></label>').join("")+'</div><div class="mcq-actions">'+(session.feedback==="immediate"?'<button class="mini-btn pb-check" data-index="'+i+'">Check answer</button>':"")+'<button class="mini-btn pb-reveal" data-index="'+i+'">Reasoning</button></div><div class="reasoning-panel">'+q.why+'</div><div class="pb-feedback" data-pb-feedback="'+i+'"></div></article>').join("")+'</div><div class="gradebar generated-gradebar"><button class="btn primary" id="gradePracticeSession">Grade Session</button><span id="practiceLiveScore"></span></div><div id="practiceResults"></div>';
 window.__practiceState=session.questions.map(()=>({attempts:0,revealed:false,checked:false}));
 document.querySelectorAll('.generated-q input[type="radio"]').forEach(x=>x.addEventListener("change",updateGeneratedProgress));
 document.querySelectorAll(".pb-reveal").forEach(b=>b.onclick=()=>{const i=+b.dataset.index,card=$('.generated-q[data-pb-q="'+i+'"]');card?.querySelector(".reasoning-panel")?.classList.toggle("show");window.__practiceState[i].revealed=true});
 document.querySelectorAll(".pb-check").forEach(b=>b.onclick=()=>checkGeneratedQuestion(+b.dataset.index,true));
 $("#gradePracticeSession")?.addEventListener("click",gradeGeneratedPractice);
 $("#rebuildPractice")?.addEventListener("click",()=>{$("#generatedPractice")?.classList.add("hidden");window.scrollTo({top:$(".builder-shell")?.offsetTop||0,behavior:"smooth"})});
 updateGeneratedProgress()
}
function updateGeneratedProgress(){
 const session=window.__practiceSession;if(!session)return;let answered=0;session.questions.forEach((q,i)=>{if(document.querySelector('input[name="pb-'+session.id+'-'+i+'"]:checked'))answered++});if($("#practiceProgress"))$("#practiceProgress").style.width=(answered/session.count*100)+"%";if($("#practiceProgressText"))$("#practiceProgressText").textContent=answered+" / "+session.count+" answered"
}
function checkGeneratedQuestion(i,showFeedback=false){
 const session=window.__practiceSession,P=PRACTICE(),q=session?.questions?.[i],state=window.__practiceState?.[i],card=$('.generated-q[data-pb-q="'+i+'"]');if(!q||!state||!card)return null;
 const sel=document.querySelector('input[name="pb-'+session.id+'-'+i+'"]:checked');card.classList.remove("correct","incorrect","needs-answer");if(!sel){card.classList.add("needs-answer");return null}
 state.attempts++;state.checked=true;const correct=+sel.value===q.answer,score=P.scoreQuestion(session,state,correct);state.correct=correct;state.score=score;card.classList.add(correct?"correct":"incorrect");
 if(showFeedback){const f=card.querySelector('[data-pb-feedback="'+i+'"]');if(f)f.innerHTML=correct?'<strong>Correct</strong><span>'+Math.round(score*100)+'% credit under '+P.policies[session.grading].name+' grading.</span>':'<strong>Try again</strong><span>This attempt is recorded. Recheck the concept and setup.</span>'}
 return {correct,score}
}
function gradeGeneratedPractice(){
 const session=window.__practiceSession,P=PRACTICE();if(!session||!P)return;let total=0,answered=0;const topicStats={};
 session.questions.forEach((q,i)=>{const state=window.__practiceState[i],sel=document.querySelector('input[name="pb-'+session.id+'-'+i+'"]:checked');if(!topicStats[q.topic])topicStats[q.topic]={n:0,score:0};topicStats[q.topic].n++;if(sel){answered++;if(!state.checked)checkGeneratedQuestion(i,false);topicStats[q.topic].score+=window.__practiceState[i].score||0;total+=window.__practiceState[i].score||0}else{$('.generated-q[data-pb-q="'+i+'"]')?.classList.add("needs-answer")}});
 const pct=session.count?Math.round(total/session.count*100):0,stats=Object.entries(topicStats).map(([topic,v])=>({topic,pct:Math.round(v.score/v.n*100),n:v.n})).sort((a,b)=>a.pct-b.pct),weak=stats.filter(x=>x.pct<75);
 const res=$("#practiceResults");if(res)res.innerHTML='<section class="practice-results-card"><div class="results-score"><strong>'+pct+'%</strong><span>'+total.toFixed(2)+' / '+session.count+' weighted points · '+answered+' answered</span></div><div class="results-insights"><div><small>STRONGEST</small><strong>'+(stats.slice().sort((a,b)=>b.pct-a.pct)[0]?.topic||"Not enough data")+'</strong></div><div><small>NEEDS WORK</small><strong>'+(weak[0]?.topic||"No major weakness detected")+'</strong></div><div><small>GRADING</small><strong>'+P.policies[session.grading].name+'</strong></div></div><div class="topic-results">'+stats.map(x=>'<div><span>'+x.topic+'</span><i><b style="width:'+x.pct+'%"></b></i><strong>'+x.pct+'%</strong></div>').join("")+'</div>'+(weak.length?'<button class="btn primary" id="practiceWeakTopics">Practice weak topics</button>':"")+'</section>';
 if(weak.length)$("#practiceWeakTopics")?.addEventListener("click",()=>{document.querySelectorAll('input[name="pb-topic"]').forEach(x=>x.checked=weak.some(w=>w.topic===x.value));document.querySelectorAll("[data-level]").forEach(i=>{const v={simple:10,medium:45,complex:35,fusion:10}[i.dataset.level];i.value=v;$('[data-level-value="'+i.dataset.level+'"]').textContent=v+"%"});$("#pbCount").value="10";updatePracticeBuilderSummary();$("#generatedPractice")?.classList.add("hidden");$(".builder-shell")?.scrollIntoView({behavior:"smooth"})});
 res?.scrollIntoView({behavior:"smooth",block:"start"})
}

function mathCrumbs(last){const m=MATH();return crumbs([["Learning Atlas","#/"],["Grade 10","#/grade-10"],[m.subject.name,"#/grade-10/mathematics-honors"],[last,""]])}
function mathTopicInsight(t){
 const map={
  functions:["A function is a machine with rules, structure, and multiple useful representations.","f(x), domain, range, inverse","Do not treat f(x) as multiplication."],
  "linear-systems":["A system asks where multiple constraints are true at the same time.","intersection · elimination","A method can be correct but a model can still be inconsistent."],
  quadratics:["Quadratic form determines what feature is easiest to see.","vertex · roots · discriminant","Choose the form that exposes the question."],
  complex:["Complex numbers extend algebra when real-number roots run out.","i² = −1","Powers of i cycle every four."],
  "polynomial-algebra":["Polynomial structure rewards factoring before brute-force expansion.","factor theorem · division","Check degree and leading term as error detectors."],
  "polynomial-functions":["Roots, multiplicity, and leading behavior predict graph shape.","zeros · end behavior","Multiplicity changes how a graph meets the x-axis."],
  radicals:["Radicals and fractional exponents are equivalent languages.","a^(m/n)","Squaring can create extraneous solutions."],
  "rational-functions":["Rational graphs are controlled by restrictions and asymptotic behavior.","holes · asymptotes","Canceled factors still leave original domain holes."],
  exponential:["Exponential change is multiplicative, not additive.","y=abˣ","Percent growth uses factor 1+r."],
  logarithms:["Logs answer the exponent question and invert exponentials.","log_b x = y ⇔ bʸ=x","Log arguments must be positive."],
  "trig-foundations":["The unit circle turns angle into coordinate and ratio.","(cosθ,sinθ)","Radians are not optional in arc-length formulas."],
  "trig-functions":["Periodic structure is controlled by amplitude, period, phase, and midline.","A sin(B(x−C))+D","Period is 2π/|B|."],
  sequences:["Sequences are discrete functions with pattern encoded recursively or explicitly.","arithmetic · geometric","Use n−1 when starting from a₁."],
  "analytic-geometry":["Equations can describe geometric loci, motion, and conic structure.","circle · conics · parametrics","Standard form exposes geometry."],
  "probability-data":["Probability and data models quantify uncertainty, not certainty.","P(A|B) · residuals","Correlation is not causation."],
  "advanced-modeling":["Honors mathematics is mostly about choosing the right representation before calculating.","model selection · diagnostics","The first wrong step matters more than the final wrong number."]
 }; return map[t.id]||[t.description,"Core relationship","Check assumptions and representation."]
}
function mathFormulaStrip(){
 const m=MATH();return '<section class="shell surface-strip"><div class="surface-strip-head"><div><div class="eyebrow">Math at-a-glance</div><h2>Keep the high-frequency relationships visible.</h2></div><a href="#/grade-10/mathematics-honors/formula-vault">Full Formula Vault ↗</a></div><div class="surface-formulas math-formulas">'+m.formulas.slice(0,8).map(f=>'<article><strong>'+f[0]+'</strong><code>'+f[1]+'</code><span>'+f[2]+'</span></article>').join("")+'</div></section>'
}
function mathHome(){
 const m=MATH(),mc=m.topics.reduce((n,t)=>n+t.modules.length,0);
 return header("Math")+'<main><section class="shell innerhero compact-hero math-hero">'+mathCrumbs("Mathematics Honors")+'<div class="eyebrow"><span class="signal"></span>Grade 10 · Honors Mathematics</div><div class="hero-split"><div><h1>'+m.subject.name+'<br><span class="gradient">'+m.subject.subtitle+'</span></h1><p class="lead">A broad Algebra II and advanced-functions prep system built to teach concepts visually, move from direct problems to synthesis, and expose the structure behind formulas.</p><div class="actions subject-hero-actions"><a class="btn primary practice-builder-cta" href="#/grade-10/mathematics-honors/practice-builder">Build My Practice</a><a class="btn" href="#/grade-10/mathematics-honors/visual-lab">Math Visual Lab</a><a class="btn" href="#/grade-10/mathematics-honors/practice-tests">Curated Tests</a></div></div><div class="surface-summary"><article><strong>'+m.topics.length+'</strong><span>topic domains</span></article><article><strong>'+mc+'</strong><span>learning modules</span></article><article><strong>'+m.visuals.length+'</strong><span>visual labs</span></article><article><strong>6</strong><span>practice tests</span></article></div></div></section>'+practiceBuilderSpotlight("math")+mathFormulaStrip()+
 '<section class="shell section"><div class="sectionhead"><div><div class="eyebrow">Topic intelligence</div><h2>See the mathematical structure before opening a lesson.</h2></div><p>Each card surfaces the idea, governing relationship, and failure mode first.</p></div><div class="topic-intelligence-grid">'+m.topics.map((t,i)=>{const x=mathTopicInsight(t);return '<article class="topic-intel math-intel"><div class="topic-intel-top"><span>'+String(i+1).padStart(2,"0")+'</span><a href="#/grade-10/mathematics-honors/topic/'+t.id+'">Open topic ↗</a></div><h3>'+t.name+'</h3><p>'+x[0]+'</p><div class="intel-row"><small>STRUCTURE</small><strong>'+x[1]+'</strong></div><div class="intel-row trap"><small>WATCH FOR</small><strong>'+x[2]+'</strong></div><div class="module-chip-row">'+t.modules.map(x=>'<span>'+x.name+'</span>').join("")+'</div></article>'}).join("")+'</div></section>'+
 '<section class="shell section"><div class="sectionhead"><div><div class="eyebrow">Practice modes</div><h2>From fluency to hidden structure.</h2></div></div><div class="home-launch-grid"><a href="#/grade-10/mathematics-honors/visual-lab"><small>SEE IT</small><strong>Math Visual Lab</strong><span>Move graphs, angles, asymptotes, and growth models directly.</span><b>↗</b></a><a href="#/grade-10/mathematics-honors/practice-builder"><small>CUSTOMIZE</small><strong>Build My Practice</strong><span>Choose topics, level mix, question count, and grading style.</span><b>↗</b></a><a href="#/grade-10/mathematics-honors/challenge-lab"><small>SYNTHESIZE</small><strong>24 Challenge problems</strong><span>Cross-topic models and diagnostic reasoning.</span><b>↗</b></a><a href="#/grade-10/mathematics-honors/formula-vault"><small>RECALL</small><strong>Formula Vault</strong><span>High-frequency relationships and usage traps.</span><b>↗</b></a></div></section></main>'+footer()
}
function mathTopic(id){
 const m=MATH(),t=m.topics.find(x=>x.id===id);if(!t)return notfound();const ins=mathTopicInsight(t);
 return header("Math")+'<main><section class="shell innerhero compact-hero">'+mathCrumbs(t.name)+'<div class="eyebrow"><span class="signal"></span>Mathematics Topic</div><h1>'+t.name+'</h1><p class="lead">'+t.description+'</p><div class="topic-brief"><article><small>BIG IDEA</small><strong>'+ins[0]+'</strong></article><article><small>STRUCTURE</small><strong>'+ins[1]+'</strong></article><article class="warn"><small>COMMON FAILURE</small><strong>'+ins[2]+'</strong></article></div></section><section class="shell section"><div class="module-grid">'+t.modules.map((m0,i)=>'<article class="module-row open insight-module math-module"><div class="module-head static"><div class="module-num">'+String(i+1).padStart(2,"0")+'</div><div class="module-title"><strong>'+m0.name+'</strong><small>'+m0.summary+'</small></div><span class="module-type">'+m0.type+'</span></div><div class="module-body"><div class="learnbox"><div class="note"><label>UNDERSTAND</label>'+m0.learn+'</div><div class="note"><label>WORKED MODEL</label>'+m0.example+'</div></div><div class="practice"><div class="micro">Guided practice</div>'+m0.practice.map((p,j)=>guidedBlock("math-"+m0.id+"-"+j,p[0],p[1],"Identify the representation, show the setup, then verify the result.")).join("")+'</div><div class="module-recap"><strong>One-minute recap</strong><p>'+m0.learn+'</p><span>Can you explain which representation exposes the answer fastest?</span></div></div></article>').join("")+'</div></section></main>'+footer()
}
function mathFormulaVault(){
 const m=MATH();return header("Math Formula Vault")+'<main><section class="shell innerhero">'+mathCrumbs("Formula Vault")+'<div class="eyebrow"><span class="signal"></span>Mathematical recall</div><h1>Math Formula Vault</h1><p class="lead">Formulas are organized around when they are useful, not just what they look like.</p><div class="formula-search"><input id="mathFormulaSearch" placeholder="Search quadratic, trig, logarithm, sequence..."></div></section><section class="shell section"><div class="formula-vault-grid">'+m.formulas.map((f,i)=>'<article class="vault-card math-vault" data-math-search="'+esc((f.join(" ")).toLowerCase())+'"><div class="micro">'+String(i+1).padStart(2,"0")+'</div><h3>'+f[0]+'</h3><code>'+f[1]+'</code><p><strong>Use it for:</strong> '+f[2]+'</p><div class="trapline">'+f[3]+'</div></article>').join("")+'</div></section></main>'+footer()
}
function mathPractice(){
 const m=MATH(),tests=m.practiceTests,first="A";
 return header("Math Practice")+'<main><section class="shell innerhero">'+mathCrumbs("Practice Tests")+'<div class="eyebrow"><span class="signal"></span>Difficulty ladder</div><h1>Math Practice Tests</h1><p class="lead">Six full practice tests and 108 questions move from direct fluency to applied reasoning, diagnostics, and cross-topic fusion.</p><div class="actions"><a class="btn primary" href="#/grade-10/mathematics-honors/practice-builder">Build My Practice</a></div></section><section class="shell section"><div class="test-tabs">'+Object.entries(tests).map(([k,t],i)=>'<button class="test-tab math-test-tab '+(i===0?"active":"")+'" data-math-test="'+k+'"><strong>'+t.title+'</strong><span>'+t.subtitle+'</span></button>').join("")+'</div><div id="mathTestMount" data-current="'+first+'"></div></section></main>'+footer()
}
function renderMathTest(key){
 const m=MATH(),t=m.practiceTests[key],mount=$("#mathTestMount");if(!t||!mount)return;
 mount.innerHTML='<div class="test-head"><div><div class="micro">'+t.title+'</div><h2>'+t.subtitle+'</h2></div><div class="test-score" id="mathTestScore">Not graded</div></div>'+t.questions.map((q,i)=>'<article class="mcq math-mcq" data-math-q="'+i+'"><div class="qtop"><span class="cat">Question '+(i+1)+'</span></div><h3>'+q.q+'</h3><div class="choices">'+q.options.map((o,j)=>'<label><input type="radio" name="math-'+key+'-'+i+'" value="'+j+'"><span>'+o+'</span></label>').join("")+'</div><div class="mcq-actions"><button class="mini-btn math-check-one" data-key="'+key+'" data-index="'+i+'">Check answer</button><button class="mini-btn reveal-reasoning">Check reasoning</button></div><div class="reasoning-panel">'+q.why+'</div></article>').join("")+'<div class="gradebar"><button class="btn primary" id="gradeMathTest">Grade entire test</button><button class="btn" id="resetMathTest">Reset</button></div>';
 bindMathTest(key)
}
function bindMathTest(key){
 const m=MATH();$$(".math-check-one").forEach(b=>b.onclick=()=>{const i=+b.dataset.index,card=$('.math-mcq[data-math-q="'+i+'"]'),sel=$('input:checked',card),q=m.practiceTests[key].questions[i];card.classList.remove("correct","incorrect","needs-answer");if(!sel){card.classList.add("needs-answer");return}card.classList.add(+sel.value===q.answer?"correct":"incorrect")});
 $("#gradeMathTest")?.addEventListener("click",()=>{let n=0,answered=0,qs=m.practiceTests[key].questions;qs.forEach((q,i)=>{const card=$('.math-mcq[data-math-q="'+i+'"]'),sel=$('input:checked',card);card.classList.remove("correct","incorrect","needs-answer");if(sel){answered++;if(+sel.value===q.answer){n++;card.classList.add("correct")}else card.classList.add("incorrect")}else card.classList.add("needs-answer")});$("#mathTestScore").textContent=n+" / "+qs.length+" · "+answered+" answered"});
 $("#resetMathTest")?.addEventListener("click",()=>renderMathTest(key));bindDynamic()
}
