 $("#gradeMathMock")?.addEventListener("click",()=>{let n=0,answered=0;t.questions.forEach((q,i)=>{const card=$('.math-mock-mcq[data-math-mock-q="'+i+'"]'),sel=$('input:checked',card);card.classList.remove("correct","incorrect","needs-answer");if(sel){answered++;if(+sel.value===q.answer){n++;card.classList.add("correct")}else card.classList.add("incorrect")}else card.classList.add("needs-answer")});$("#mathMockScore").textContent=n+" / "+t.questions.length+" · "+answered+" answered"});
